// Water caustics shimmer on a helix lamp.
// Per-LED maths is all fixed-point; the two interference waves are advanced in
// update() so the speed sliders never rescale elapsed time.
uniform float speed1 : 0.0 .. 5.0 = 1.0;   // wave drift 1 (turns / s)
uniform float speed2 : 0.0 .. 5.0 = 0.6;   // wave drift 2 (turns / s)
uniform float density : 1.0 .. 12.0 = 5.0; // spatial frequency of the web
uniform float shimmer : 0.0 .. 1.0 = 0.6;  // sparkle contrast
uniform float glow : 0.0 .. 1.0 = 0.35;    // ambient body light
uniform vec3 tint : color = 0.35, 0.7, 1.0;

state fixed ph1;   // wave 1 phase, TURNS
state fixed ph2;   // wave 2 phase, TURNS
state fixed k;     // spatial frequency
state fixed sh;    // shimmer amount
state fixed gl;    // ambient glow
state fixed ti;    // tint r
state fixed tg;    // tint g
state fixed tb;    // tint b

void update() {
  ph1 = fract(ph1 + fixed(dt * speed1));
  ph2 = fract(ph2 + fixed(dt * speed2));
  k  = fixed(density);
  sh = fixed(shimmer);
  gl = fixed(glow);
  ti = fixed(tint.x);
  tg = fixed(tint.y);
  tb = fixed(tint.z);
}

vec3 shade(Led led) {
  fixed x = fixed(led.pos.x);
  fixed z = fixed(led.pos.z);
  fixed y = fixed(led.pos.y);

  // two interfering wave fields -> sharp caustic web via squared sum
  fixed a = sin(x * k + ph1) + sin(z * k * fixed(1.13) + ph2);
  fixed b = sin((x + z) * k * fixed(0.71) - ph1 * fixed(0.6) + ph2 * fixed(0.4));
  fixed w = a * a + b * b;              // 0..8
  fixed c = w - fixed(5.0);             // only the bright ridges stay
  c = c * c;                            // sharpen the filaments
  c = clamp(c * fixed(0.06), fixed(0.0), fixed(1.0));

  // slow vertical shimmer so the web crawls and sparkles
  fixed tw = sin(y * fixed(28.0) + ph1 * fixed(6.0) + ph2 * fixed(4.0)) * fixed(0.5) + fixed(0.5);
  c = c * (fixed(0.6) + sh * tw);

  fixed r = ti * c + gl * ti * fixed(0.25);
  fixed g = tg * c + gl * tg * fixed(0.25);
  fixed b2 = tb * c + gl * tb * fixed(0.25);
  return vec3(float(r), float(g), float(b2));
}
